-- 1) Cấu hình trên Primary PostgreSQL (yêu cầu wal_level = logical trong postgresql.conf)
ALTER SYSTEM SET max_slot_wal_keep_size = '30GB';
SELECT pg_reload_conf();

ALTER TABLE erp_sku_live REPLICA IDENTITY FULL;
ALTER TABLE crm_price_policies REPLICA IDENTITY FULL;

CREATE PUBLICATION domation_ai_cdc_pub
  FOR TABLE erp_sku_live, crm_price_policies
  WITH (publish = 'insert, update, delete');

// 2) TypeScript Consumer đọc luồng pgoutput & định tuyến thông minh (tránh gọi Embedding dư thừa)
import { LogicalReplicationService, PgoutputPlugin } from 'pg-logical-replication';
import { redis } from './redisClient';
import { vectorQueue } from './queues';

const service = new LogicalReplicationService({ connectionString: process.env.PG_CDC_URL });
const plugin = new PgoutputPlugin({ protoVersion: 1, publicationNames: ['domation_ai_cdc_pub'] });

service.on('data', async (lsn: string, log: any) => {
  if (log.tag === 'delete' && log.relation?.name === 'erp_sku_live') {
    await redis.del(`sku:live:${log.key.sku_code}`);
    await vectorQueue.add('tombstone-sku', { skuCode: log.key.sku_code, lsn }, { jobId: `del-${lsn}` });
    return service.acknowledge(lsn);
  }

  if ((log.tag === 'insert' || log.tag === 'update') && log.relation?.name === 'erp_sku_live') {
    const nextRow = log.new;
    const prevRow = log.old ?? {};

    // Luồng 1: Cập nhật Hot-Cache cho AI Tool Calling trong <15ms
    await redis.hset(`sku:live:${nextRow.sku_code}`, {
      price_vnd: String(nextRow.unit_price_vnd),
      stock_qty: String(nextRow.stock_available),
      status: nextRow.sale_status,
      updated_lsn: lsn,
    });

    // Luồng 2: Chỉ tái lập Vector Embedding khi trường ngữ nghĩa đổi hoặc mới tạo
    const semanticChanged = log.tag === 'insert' || prevRow.spec_markdown !== nextRow.spec_markdown;
    if (semanticChanged) {
      await vectorQueue.add('re-embed-sku', { skuCode: nextRow.sku_code, spec: nextRow.spec_markdown, lsn }, {
        jobId: `embed-${nextRow.sku_code}-${lsn.replace('/', '-')}`,
      });
    }
    await service.acknowledge(lsn);
  }
});

service.subscribe(plugin, 'domation_ai_cdc_slot');
